 20	constexpr int kSwatchesPerRow = 6;
 21	
 22	HeaderMenuItem separator()
 23	{
 24	    HeaderMenuItem item;
 25	    item.separator = true;
 26	    item.title     = true;
 27	    return item;
 28	}
 29	
 30	HeaderMenuItem title_row(const wxString& text)
 31	{
 32	    HeaderMenuItem item;
 33	    item.title = true;
 34	    item.label = text;
 35	    return item;
 36	}
 37	
 38	wxString middot() { return wxString::FromUTF8(" \xC2\xB7 "); }
 39	
 40	// "Cold White · eSun" as one row label; the brand reads as secondary because
 41	// the row paints everything after the separator in text/secondary would be a
 42	// second text run. Keeping it in the label keeps ellipsis behaviour correct,
 43	// and the brand is what gets dropped first when the name is long.
 44	wxString spool_label(const Workspace::Spool& spool)
 45	{
 46	    wxString label = wxString::FromUTF8(spool.name);
 47	    if (!spool.brand.empty()) label += middot() + wxString::FromUTF8(spool.brand);
 48	    return label;
 49	}
 50	
 51	bool matches(const SetupCommands::FilamentInfo& filament, const wxString& query)
 52	{
 53	    if (query.empty()) return true;
 54	    const wxString needle = query.Lower();
 55	    return filament.alias.Lower().Contains(needle) || filament.vendor.Lower().Contains(needle);
 56	}
