 76	void SpoolMenu::select(const Ptr& self, const Workspace::Spool& spool)
 77	{
 78	    Host& host = self->m_host;
 79	    // Order matters: the preset switch first, because it can pull a colour of
 80	    // its own from the preset, then the spool's colour over the top, then the
 81	    // recency stamp. The chip refreshes from Orca's own settings-changed
 82	    // notification, not from here.
 83	    if (!SetupCommands::select_filament_preset(*host.plater, spool.filament_preset))
 84	        return;
 85	    const wxColour colour(wxString::FromUTF8(spool.colour));
 86	    if (colour.IsOk())
 87	        SetupCommands::set_filament_colour(*host.plater, colour);
 88	    host.store->touch(spool.id);
 89	    if (host.selected) host.selected(spool);
 90	}
