 92	// Brings the spool list back after a step that had to close the popup.
 93	void SpoolMenu::reopen(const Ptr& self)
 94	{
 95	    if (!self->m_anchor) return;
 96	    open(self->m_owner, self->m_theme, self->m_dark, self->m_host, *self->m_anchor);
 97	}
