 99	void SpoolMenu::show_spools(const Ptr& self)
100	{
101	    auto* menu = self->m_menu.get();
102	    if (menu == nullptr) return; // the popup went away; nothing to rebuild
103	    menu->set_header_builder(nullptr);
104	    const auto printer = SetupCommands::current_printer();
105	    const auto current = self->m_host.store->current(printer.preset_name,
106	                                               SetupCommands::current_filament().preset_name,
107	                                               SetupCommands::current_colour().ToStdString());
108	
109	    std::vector<HeaderMenuItem> rows;
110	    rows.push_back(title_row(wxString::Format(_L("SPOOLS ON %s"), printer.nickname.Upper())));
111	
112	    // Never truncated and never scrolled: a person keeps three to fifteen
113	    // spools, and the whole design rests on the right one being one click away.
114	    for (const Workspace::Spool& spool : self->m_host.store->spools_for(printer.preset_name)) {
115	        HeaderMenuItem row;
116	        row.label            = spool_label(spool);
117	        row.decoration.dot   = wxColour(wxString::FromUTF8(spool.colour));
118	        row.decoration.check = current.has_value() && current->id == spool.id;
119	        row.invoke           = [self, spool] { SpoolMenu::select(self, spool); };
120	        row.row_action       = HeaderIcon::More;
121	        row.invoke_row_action = [self, spool] { show_row_menu(self, spool); };
122	        rows.push_back(std::move(row));
123	    }
124	
125	    HeaderMenuItem other;
126	    other.separator          = true;
127	    other.label              = _L("Other spool…");
128	    other.decoration.trailing = HeaderIcon::Right;
129	    other.keeps_open         = true;
130	    other.invoke             = [self] { show_other_spool(self); };
131	    rows.push_back(std::move(other));
132	
133	    menu->replace_items(std::move(rows));
134	}
135	
136	void SpoolMenu::show_row_menu(const Ptr& self, const Workspace::Spool& spool)
137	{
138	    auto* menu = self->m_menu.get();
139	    if (menu == nullptr) return; // the popup went away; nothing to rebuild
140	    menu->set_header_builder(nullptr);
141	    std::vector<HeaderMenuItem> rows;
142	
143	    HeaderMenuItem back;
144	    back.label      = wxString::FromUTF8(spool.name);
145	    back.icon       = HeaderIcon::Back;
146	    back.keeps_open = true;
147	    back.invoke     = [self] { show_spools(self); };
148	    rows.push_back(std::move(back));
149	    rows.push_back(separator());
150	
151	    HeaderMenuItem recolour;
152	    recolour.label      = _L("Change colour…");
153	    // NOT keeps_open. The system colour panel has no accept or cancel button
154	    // of its own on macOS, so its window frame is the only way out -- and a
155	    // transient popup renders above it and covers that frame. The popup has to
156	    // be gone before the dialog appears, or the person is trapped.
157	    recolour.invoke     = [self, spool] {
158	        wxColourData data;
159	        data.SetChooseFull(true);
160	        data.SetColour(wxColour(wxString::FromUTF8(spool.colour)));
161	        wxColourDialog dialog(self->m_owner, &data);
162	        dialog.CenterOnParent();
163	        if (dialog.ShowModal() != wxID_OK) { reopen(self); return; }
164	        const wxColour picked = dialog.GetColourData().GetColour();
165	        self->m_host.store->recolour(spool.id, picked.GetAsString(wxC2S_HTML_SYNTAX).ToStdString());
166	        // Recolouring the spool the project is on must move the project too,
167	        // or the chip would show a colour the print will not use.
168	        if (spool.filament_preset == SetupCommands::current_filament().preset_name &&
169	            spool.colour == SetupCommands::current_colour().ToStdString())
170	            SetupCommands::set_filament_colour(*self->m_host.plater, picked);
171	        if (self->m_host.store_changed) self->m_host.store_changed();
172	        reopen(self);
173	    };
174	    rows.push_back(std::move(recolour));
175	
176	    HeaderMenuItem rename;
177	    rename.label      = _L("Rename…");
178	    rename.invoke     = [self, spool] {
179	        wxTextEntryDialog dialog(self->m_owner, _L("Spool name"), _L("Rename spool"), wxString::FromUTF8(spool.name));
180	        if (dialog.ShowModal() == wxID_OK && !dialog.GetValue().Trim().empty()) {
181	            self->m_host.store->rename(spool.id, dialog.GetValue().Trim().ToStdString());
182	            if (self->m_host.store_changed) self->m_host.store_changed();
183	        }
184	        reopen(self);
185	    };
186	    rows.push_back(std::move(rename));
187	    rows.push_back(separator());
188	
189	    // Deferred in this slice, rendered so the shape of the menu is honest
190	    // about what is coming rather than growing later.
191	    HeaderMenuItem tune;
192	    tune.label   = _L("Tune with the agent");
193	    tune.enabled = false;
194	    rows.push_back(std::move(tune));
195	
196	    HeaderMenuItem reset;
197	    reset.label   = _L("Reset tuning");
198	    reset.enabled = false;
199	    rows.push_back(std::move(reset));
200	    rows.push_back(separator());
201	
202	    HeaderMenuItem settings;
203	    settings.label  = _L("Filament settings…");
204	    settings.invoke = [] { SetupCommands::open_settings_tab(Preset::TYPE_FILAMENT); };
205	    rows.push_back(std::move(settings));
206	
207	    HeaderMenuItem remove;
208	    remove.label            = _L("Remove from this printer");
209	    remove.decoration.danger = true;
210	    remove.keeps_open       = true;
211	    remove.invoke           = [self, spool] {
212	        // Removing the spool forgets a note about a physical reel; it changes
213	        // nothing about the project, which keeps the preset and colour it has.
214	        self->m_host.store->remove(spool.id);
215	        if (self->m_host.store_changed) self->m_host.store_changed();
216	        show_spools(self);
217	    };
218	    rows.push_back(std::move(remove));
219	
220	    menu->replace_items(std::move(rows));
221	}
