223	void SpoolMenu::show_other_spool(const Ptr& self)
224	{
225	    auto* menu = self->m_menu.get();
226	    if (menu == nullptr) return; // the popup went away; nothing to rebuild
227	    const auto printer = SetupCommands::current_printer();
228	
229	    // The search field lives above the rows and keeps focus while the result
230	    // list rebuilds under it on every keystroke.
231	    menu->set_header_builder([self](wxWindow* parent) -> wxWindow* {
232	        const auto& palette = self->m_theme.palette(self->m_dark);
233	        auto* field = new wxTextCtrl(parent, wxID_ANY, self->m_search, wxDefaultPosition, wxDefaultSize, wxTE_PROCESS_ENTER);
234	        field->SetHint(_L("Search filaments"));
235	        field->SetFont(Label::Body_14);
236	        field->SetBackgroundColour(palette.surface_subtle);
237	        field->SetForegroundColour(palette.text_primary);
238	        field->SetMinSize(wxSize(-1, field->FromDIP(28)));
239	        field->Bind(wxEVT_TEXT, [self](wxCommandEvent& event) {
240	            self->m_search = event.GetString();
241	            // Rebuilding destroys this control, so leave the current event
242	            // first and let the rebuild re-create the field with the text.
243	            // The popup owns the deferral: if it dismisses in between, the
244	            // weak reference drops the call and this controller is gone too.
245	            self->m_owner->CallAfter([self, alive = wxWeakRef<wxWindow>(self->m_menu)] {
246	                if (alive) show_other_spool(self);
247	            });
248	        });
249	        self->m_search_field = field;
250	        return field;
251	    }, 1); // below the back row, as the design places it
252	
253	    std::vector<HeaderMenuItem> rows;
254	    // The title is also the way back one step; without it the only exit from
255	    // this step is dismissing the whole menu. It names the filter in force, so
256	    // a shortened list is never mistaken for the whole list, and going back
257	    // from the generic list lands on the full one rather than leaving the
258	    // menu.
259	    HeaderMenuItem back;
260	    back.label      = self->m_generic_only
261	                        ? wxString::Format(_L("GENERIC PRESETS · FITS %s · %g MM"), printer.nickname.Upper(), printer.nozzle)
262	                        : wxString::Format(_L("OTHER SPOOL · FITS %s · %g MM"), printer.nickname.Upper(), printer.nozzle);
263	    back.icon       = HeaderIcon::Back;
264	    back.keeps_open = true;
265	    back.invoke     = [self] {
266	        if (self->m_generic_only) { self->m_generic_only = false; show_other_spool(self); return; }
267	        self->m_search.clear();
268	        show_spools(self);
269	    };
270	    rows.push_back(std::move(back));
271	
272	    for (const auto& filament : SetupCommands::compatible_filaments()) {
273	        // Whether a preset is generic is a property of the preset, so it is an
274	        // exact test on the vendor the profile declares -- never a text match,
275	        // which would both admit branded presets that happen to read "generic"
276	        // and drop generic ones that do not.
277	        if (self->m_generic_only && filament.vendor != SetupCommands::kGenericVendor) continue;
278	        if (!matches(filament, self->m_search)) continue;
279	        HeaderMenuItem row;
280	        // The step already says every row is generic; repeating the vendor on
281	        // each one would say it a second time and eat the width the name needs.
282	        row.label = filament.vendor.empty() || self->m_generic_only
283	                      ? filament.alias : filament.alias + middot() + filament.vendor;
284	        // A dashed ring: this preset is not a spool yet, and has no colour.
285	        row.decoration.dot = wxColour();
286	        row.keeps_open     = true;
287	        row.invoke         = [self, filament] { show_new_spool(self, filament); };
288	        rows.push_back(std::move(row));
289	    }
290	
291	    // Offered only from the full list: once the filter is on, the title row is
292	    // the affordance, and a row that turns on what is already on says nothing.
293	    if (!self->m_generic_only) {
294	        HeaderMenuItem generic;
295	        generic.separator  = true;
296	        generic.label      = _L("Generic preset…");
297	        generic.keeps_open = true;
298	        generic.invoke     = [self] {
299	            // Generic presets are ordinary compatible presets whose profile
300	            // declares the "Generic" vendor, so this is the same list
301	            // filtered, not a separate source. Whatever was typed still
302	            // applies; nothing is typed on the person's behalf.
303	            self->m_generic_only = true;
304	            show_other_spool(self);
305	        };
306	        rows.push_back(std::move(generic));
307	    }
308	
309	    HeaderMenuItem import;
310	    import.separator = self->m_generic_only; // the rule the generic row carried
311	    import.label  = _L("Import a preset file…");
312	    import.invoke = [] { SetupCommands::import_preset_file(); };
313	    rows.push_back(std::move(import));
314	
315	    menu->replace_items(std::move(rows));
316	    // The rebuild replaced the field, so focus and caret have to be restored
317	    // or every keystroke would land at the start of what was already typed.
318	    if (self->m_search_field) {
319	        self->m_search_field->SetFocus();
320	        self->m_search_field->SetInsertionPointEnd();
321	    }
322	}
