324	void SpoolMenu::show_new_spool(const Ptr& self, const SetupCommands::FilamentInfo& preset)
325	{
326	    auto* menu = self->m_menu.get();
327	    if (menu == nullptr) return; // the popup went away; nothing to rebuild
328	    const auto printer = SetupCommands::current_printer();
329	    const bool first   = self->m_new_preset != preset.preset_name;
330	    if (first) {
331	        self->m_new_preset      = preset.preset_name;
332	        self->m_new_material    = preset.material.empty() ? preset.alias : preset.material;
333	        self->m_new_vendor      = preset.vendor;
334	        self->m_new_colour      = wxColour(wxString::FromUTF8(SetupCommands::swatches().front().hex));
335	        self->m_new_name_edited = false;
336	    }
337	    if (!self->m_new_name_edited) {
