    31	void SliceReviewPanel::set_report(Workspace::SliceIdentity identity, std::vector<std::string> findings)
    32	{
    33	    if (identity == m_identity && findings == m_findings) return;
    34	    m_identity = identity;
    35	    m_findings = std::move(findings);
    36	    m_seen.clear();
    37	    m_notified = false;
    38	    wxString accessible;
    39	    for (const auto& finding : m_findings) accessible += wxString::FromUTF8(finding) + "\n";
    40	    SetLabel(accessible);
    41	    Scroll(0,0);
    42	    Refresh();
    43	}
