    45	void SliceReviewPanel::paint(wxPaintEvent&)
    46	{
    47	    wxAutoBufferedPaintDC dc(this);
    48	    const auto& palette = m_theme.palette(m_dark);
    49	    dc.SetBackground(wxBrush(palette.surface_subtle)); dc.Clear();
    50	    PrepareDC(dc);
    51	    dc.SetTextForeground(palette.text_primary);
    52	    dc.SetFont(Label::Head_12);
    53	    const int margin = FromDIP(12);
    54	    int y = margin;
    55	    dc.DrawText(_L("Check print"),margin,y);
    56	    y += dc.GetCharHeight()+FromDIP(8);
    57	    dc.SetFont(GetFont());
    58	    int scroll_x, scroll_y;
    59	    CalcUnscrolledPosition(0,0,&scroll_x,&scroll_y);
    60	    if (m_findings.empty()) {
    61	        dc.DrawText(_L("No reported findings. Inspect the sliced result before printing."),margin,y);
    62	        y += dc.GetCharHeight();
    63	    }
    64	    std::vector<wxString> lines;
    65	    for (size_t i=0;i<m_findings.size();++i) {
    66	        WrappedText wrapped;
    67	        wrapped.Wrap(this,wxString::Format("%d. ",int(i+1))+wxString::FromUTF8(m_findings[i]),
    68	                     std::max(FromDIP(40),GetClientSize().x-2*margin));
    69	        lines.insert(lines.end(),wrapped.lines.begin(),wrapped.lines.end());
    70	    }
    71	    if (m_seen.size() != lines.size()) m_seen.assign(lines.size(),false);
    72	    const int line_height = dc.GetCharHeight()+FromDIP(4);
    73	    for (size_t i=0;i<lines.size();++i) {
    74	        dc.DrawText(lines[i],margin,y);
    75	        // Scrolling to the last finding must not count skipped lines as read.
    76	        if (y >= scroll_y && y+line_height <= scroll_y+GetClientSize().y) m_seen[i] = true;
    77	        y += line_height;
    78	    }
    79	    SetVirtualSize(wxSize(GetClientSize().x,y+margin));
    80	    if (!m_notified && !m_findings.empty() && IsShownOnScreen() &&
    81	        std::all_of(m_seen.begin(),m_seen.end(),[](bool seen) { return seen; })) {
    82	        m_notified = true;
    83	        CallAfter([self=wxWeakRef<SliceReviewPanel>(this),identity=m_identity,findings=m_findings] {
    84	            if (self && self->m_identity == identity && self->m_findings == findings)
    85	                self->m_notified = self->IsShownOnScreen() && self->m_displayed(identity,findings);
    86	        });
    87	    }
    88	}
