 26	std::string utf8(const wxString& value) { return value.ToUTF8().data(); }
 27	
 28	std::string command_path(const std::string& command)
 29	{
 30	    wxString path;
 31	    wxGetEnv("PATH", &path);
 32	#ifdef _WIN32
 33	    wxStringTokenizer directories(path, ";");
 34	    const auto filename = wxString::FromUTF8(command + ".exe");
 35	#else
 36	    wxStringTokenizer directories(path, ":");
 37	    const auto filename = wxString::FromUTF8(command);
 38	#endif
 39	    while (directories.HasMoreTokens()) {
 40	        const auto directory = directories.GetNextToken();
 41	        const auto candidate = wxFileName(directory, filename).GetFullPath();
 42	        if (!directory.empty() && wxFileName::IsFileExecutable(candidate)) return utf8(candidate);
 43	    }
 44	    // GUI launches on macOS often inherit a shorter PATH than a login shell.
 45	#ifndef _WIN32
 46	    for (const auto& directory : {wxGetHomeDir() + "/.local/bin", wxString("/opt/homebrew/bin"), wxString("/usr/local/bin")}) {
 47	        const auto candidate = wxFileName(directory, filename).GetFullPath();
 48	        if (wxFileName::IsFileExecutable(candidate)) return utf8(candidate);
 49	    }
 50	#endif
 51	    return {};
 52	}
