 75	McpSetupResult run_mcp_setup_command(wxWindow* parent, const std::vector<std::string>& arguments)
 76	{
 77	    if (arguments.empty()) throw std::invalid_argument("Missing setup executable");
 78	    wxDialog progress(parent, wxID_ANY, "Connecting AI tool", wxDefaultPosition, parent->FromDIP(wxSize(460, 140)));
 79	    auto* label = new wxStaticText(&progress, wxID_ANY, "Saving the MCP entry using the client's own CLI...");
 80	    auto* layout = new wxBoxSizer(wxVERTICAL);
 81	    layout->Add(label, 1, wxEXPAND | wxALL, progress.FromDIP(16));
 82	    progress.SetSizer(layout);
 83	    wxProcess process(&progress);
 84	    process.Redirect();
 85	    std::vector<wxString> values;
 86	    for (const auto& value : arguments) values.push_back(wxString::FromUTF8(value));
 87	    std::vector<const wchar_t*> argv;
 88	    for (const auto& value : values) argv.push_back(value.wc_str());
 89	    argv.push_back(nullptr);
 90	    const auto pid = wxExecute(argv.data(), wxEXEC_ASYNC | wxEXEC_HIDE_CONSOLE, &process);
 91	    if (pid <= 0) return {false, "Could not start the client CLI. Use Copy or check its installation."};
 92	    process.CloseOutput();
 93	    std::string output;
 94	    bool timed_out = false;
 95	    int exit_code = -1;
 96	    const auto started = std::chrono::steady_clock::now();
 97	    auto drain = [&] {
 98	        for (auto* stream : {process.GetInputStream(), process.GetErrorStream()}) {
 99	            while (stream && stream->CanRead()) {
100	                char buffer[4096];
101	                stream->Read(buffer, sizeof buffer);
102	                const auto size = stream->LastRead();
103	                if (!size) break;
104	                if (output.size() < 65536) output.append(buffer, std::min(size, 65536 - output.size()));
105	            }
106	        }
107	    };
108	    wxTimer timer(&progress);
109	    progress.Bind(wxEVT_TIMER, [&](wxTimerEvent&) {
110	        drain();
111	        const auto elapsed = std::chrono::steady_clock::now() - started;
112	        if (!timed_out && elapsed > std::chrono::seconds(30)) {
113	            timed_out = true;
114	            label->SetLabel("The setup command timed out. Stopping it...");
115	            wxProcess::Kill(pid, wxSIGTERM);
116	        } else if (timed_out && elapsed > std::chrono::seconds(32)) wxProcess::Kill(pid, wxSIGKILL);
117	    });
118	    progress.Bind(wxEVT_CLOSE_WINDOW, [&](wxCloseEvent& event) {
119	        if (event.CanVeto()) event.Veto(); // Keep the owned process alive only while its monitor exists.
120	    });
121	    // wxDialog handles Cancel separately from window-close events. Do not
122	    // destroy the process monitor while the CLI may still be saving settings.
123	    progress.Bind(wxEVT_BUTTON, [](wxCommandEvent&) {}, wxID_CANCEL);
124	    progress.Bind(wxEVT_END_PROCESS, [&](wxProcessEvent& event) {
125	        drain(); exit_code = event.GetExitCode(); timer.Stop(); progress.EndModal(wxID_OK);
126	    });
127	    timer.Start(30);
128	    progress.ShowModal();
129	    if (timed_out) return {false, "Setup timed out; the client config may have changed. Inspect it before trying again.\n" + output};
130	    return {exit_code == 0, "Client CLI exited with code " + std::to_string(exit_code) + ".\n" + output};
131	}
