133	void start_mcp_setup_command(wxWindow* parent, const std::vector<std::string>& arguments,
134	                             std::function<void(McpSetupResult)> done)
135	{
136	    if (arguments.empty()) {
137	        done({false, "Missing setup executable"});
138	        return;
139	    }
140	    struct Watch : wxEvtHandler {
141	        wxProcess process;
142	        wxTimer timer;
143	        std::function<void(McpSetupResult)> done;
144	        std::string output;
145	        std::chrono::steady_clock::time_point started;
146	        long pid{0};
147	        bool timed_out{false};
148	        bool finished{false};
149	        Watch(wxWindow*, std::function<void(McpSetupResult)> complete)
150	            : process(this), timer(this), done(std::move(complete)), started(std::chrono::steady_clock::now())
151	        {}
152	        void drain()
153	        {
154	            for (auto* stream : {process.GetInputStream(), process.GetErrorStream()}) {
155	                while (stream && stream->CanRead()) {
156	                    char buffer[4096];
157	                    stream->Read(buffer, sizeof buffer);
158	                    const auto size = stream->LastRead();
159	                    if (!size) break;
160	                    if (output.size() < 65536) output.append(buffer, std::min(size, 65536 - output.size()));
161	                }
162	            }
163	        }
164	        void finish(McpSetupResult result)
165	        {
166	            if (finished) return;
167	            finished = true;
168	            timer.Stop();
169	            auto complete = std::move(done);
170	            complete(std::move(result));
171	            CallAfter([this] { delete this; });
172	        }
173	    };
174	    auto* watch = new Watch(parent, std::move(done));
175	    std::vector<wxString> values;
176	    for (const auto& value : arguments) values.push_back(wxString::FromUTF8(value));
177	    std::vector<const wchar_t*> argv;
178	    for (const auto& value : values) argv.push_back(value.wc_str());
179	    argv.push_back(nullptr);
180	    watch->pid = wxExecute(argv.data(), wxEXEC_ASYNC | wxEXEC_HIDE_CONSOLE, &watch->process);
181	    if (watch->pid <= 0) {
182	        watch->finish({false, "Could not start the client CLI. Use Copy or check its installation."});
183	        return;
184	    }
185	    watch->process.CloseOutput();
186	    watch->Bind(wxEVT_TIMER, [watch](wxTimerEvent&) {
187	        watch->drain();
188	        const auto elapsed = std::chrono::steady_clock::now() - watch->started;
189	        if (!watch->timed_out && elapsed > std::chrono::seconds(30)) {
190	            watch->timed_out = true;
191	            wxProcess::Kill(watch->pid, wxSIGTERM);
192	        } else if (watch->timed_out && elapsed > std::chrono::seconds(32))
193	            wxProcess::Kill(watch->pid, wxSIGKILL);
194	    });
195	    watch->Bind(wxEVT_END_PROCESS, [watch](wxProcessEvent& event) {
196	        if (event.GetPid() != watch->pid) { event.Skip(); return; }
197	        watch->drain();
198	        if (watch->timed_out)
199	            watch->finish({false, "Setup timed out; the client config may have changed. Inspect it before trying again.\n" + watch->output});
200	        else
201	            watch->finish({event.GetExitCode() == 0,
202	                           "Client CLI exited with code " + std::to_string(event.GetExitCode()) + ".\n" + watch->output});
203	    });
204	    watch->timer.Start(30);
205	}
