207	void show_mcp_connection_dialog(wxWindow* parent, const ShellTheme& theme, const std::string& discovery_path,
208	                                const std::string& live_url, const std::string& startup_error)
209	{
210	#ifdef _WIN32
211	    constexpr bool windows = true;
212	    const std::string helper_name = "jusprin-mcp.exe";
213	#else
214	    constexpr bool windows = false;
215	    const std::string helper_name = "jusprin-mcp";
216	#endif
217	    const auto executable = std::filesystem::u8path(utf8(wxStandardPaths::Get().GetExecutablePath()));
218	    const auto bridge = executable.parent_path() / helper_name;
219	    auto launcher = bridge;
220	    std::vector<std::string> launch_arguments;
221	#if defined(__linux__)
222	    wxString appimage;
223	    if (wxGetEnv("APPIMAGE", &appimage) && !appimage.empty()) {
224	        launcher = std::filesystem::u8path(utf8(appimage));
225	        launch_arguments.emplace_back("--mcp-bridge");
226	    }
227	#endif
228	    const auto entries = Mcp::connection_entries(launcher.u8string(), discovery_path, windows, launch_arguments);
229	    const auto home = std::filesystem::u8path(utf8(wxGetHomeDir()));
230	#ifdef __APPLE__
231	    const auto config_home = home / "Library" / "Application Support";
232	#elif defined(_WIN32)
233	    wxString appdata;
234	    wxGetEnv("APPDATA", &appdata);
235	    const auto config_home = std::filesystem::u8path(utf8(appdata));
236	#else
237	    wxString xdg;
238	    wxGetEnv("XDG_CONFIG_HOME", &xdg);
239	    const auto config_home = xdg.empty() ? home / ".config" : std::filesystem::u8path(utf8(xdg));
240	#endif
241	    const std::vector<std::filesystem::path> configs{
242	        home / ".claude.json", home / ".codex" / "config.toml",
243	        config_home / "Claude" / "claude_desktop_config.json",
244	        config_home / "Claude" / "claude_desktop_config.json",
245	        home / ".cursor" / "mcp.json", config_home / "Code" / "User" / "mcp.json"
246	    };
247	    wxDialog dialog(parent, wxID_ANY, "Connect AI tools", wxDefaultPosition, parent->FromDIP(wxSize(760, 550)),
248	                    wxDEFAULT_DIALOG_STYLE | wxRESIZE_BORDER);
249	    const auto& colors = theme.palette(GUI_App::dark_mode());
250	    dialog.SetBackgroundColour(colors.surface_raised);
251	    dialog.SetForegroundColour(colors.text_primary);
252	    auto* layout = new wxBoxSizer(wxVERTICAL);
253	    const int gap = dialog.FromDIP(12);
254	    auto* intro = new wxStaticText(&dialog, wxID_ANY,
255	        "Connect a local AI tool to the open JusPrin project. Changes still require approval in the Agent panel.\n"
256	        "Copy the entry, or choose Connect and review the proposed change before saving it.");
257	    intro->Wrap(dialog.FromDIP(710));
258	    layout->Add(intro, 0, wxEXPAND | wxALL, gap);
259	    auto* clients = new wxChoice(&dialog, wxID_ANY);
260	    for (std::size_t i = 0; i < entries.size(); ++i) {
261	        std::error_code error;
262	        const bool detected = std::filesystem::exists(configs[i], error) || !command_path(entries[i].id).empty();
263	        clients->Append(wxString::FromUTF8((detected ? "Detected: " : "Other: ") + entries[i].name));
264	    }
265	    clients->SetSelection(0);
266	    clients->SetName("MCP client");
267	    layout->Add(clients, 0, wxEXPAND | wxLEFT | wxRIGHT, gap);
268	    auto* instructions = new wxStaticText(&dialog, wxID_ANY, "");
269	    layout->Add(instructions, 0, wxEXPAND | wxALL, gap);
270	    auto* entry = new wxTextCtrl(&dialog, wxID_ANY, "", wxDefaultPosition, wxDefaultSize,
271	                                 wxTE_MULTILINE | wxTE_READONLY);
272	    entry->SetName("MCP connection entry");
273	    layout->Add(entry, 1, wxEXPAND | wxLEFT | wxRIGHT, gap);
274	    auto* status = new wxStaticText(&dialog, wxID_ANY, "");
275	    layout->Add(status, 0, wxEXPAND | wxALL, gap);
276	    auto refresh = [&] {
277	        const auto index = std::size_t(clients->GetSelection());
278	        const auto& selected = entries[index];
279	        std::string guidance = selected.cli ? (windows ? "Run in PowerShell." : "Run in your terminal.") :
280	            "Merge this entry into " + configs[index].u8string() + ". Keep existing servers and settings.";
281	        if (selected.id == "cowork") guidance += " Requires a local Cowork session; cloud sessions cannot reach this helper.";
282	        if (selected.id == "codex") guidance += " For approvals longer than 60 seconds, raise tool_timeout_sec in the JusPrin MCP config.";
283	        instructions->SetLabel(wxString::FromUTF8(guidance));
284	        instructions->Wrap(dialog.FromDIP(710));
285	        entry->SetValue(wxString::FromUTF8(selected.text));
286	        status->SetLabel("");
287	        dialog.Layout();
288	    };
289	    clients->Bind(wxEVT_CHOICE, [&](wxCommandEvent&) { refresh(); });
290	    auto* disclosure = new wxCollapsiblePane(&dialog, wxID_ANY, "Direct HTTP (developer use)");
291	    auto* details = new wxBoxSizer(wxVERTICAL);
292	    const auto diagnostic = live_url.empty() ? "MCP could not start: " + startup_error :
293	        live_url + "\nThis URL can change after restarting JusPrin. Local requests need no authentication.";
294	    details->Add(new wxTextCtrl(disclosure->GetPane(), wxID_ANY, wxString::FromUTF8(diagnostic), wxDefaultPosition,
295	                              dialog.FromDIP(wxSize(-1, 70)), wxTE_MULTILINE | wxTE_READONLY), 1, wxEXPAND);
296	    disclosure->GetPane()->SetSizer(details);
297	    disclosure->Bind(wxEVT_COLLAPSIBLEPANE_CHANGED, [&](wxCollapsiblePaneEvent&) { dialog.Layout(); });
298	    layout->Add(disclosure, 0, wxEXPAND | wxLEFT | wxRIGHT, gap);
299	    auto* buttons = new wxBoxSizer(wxHORIZONTAL);
300	    auto* copy = new wxButton(&dialog, wxID_ANY, "Copy");
301	    copy->Bind(wxEVT_BUTTON, [&](wxCommandEvent&) {
302	        if (!wxTheClipboard->Open()) { status->SetLabel("Clipboard is busy. Try Copy again."); return; }
303	        const bool copied = wxTheClipboard->SetData(new wxTextDataObject(entry->GetValue()));
304	        wxTheClipboard->Close();
305	        status->SetLabel(copied ? "Copied. No client settings were changed." : "Could not copy the entry.");
306	    });
307	    buttons->Add(copy);
308	    auto* connect = new wxButton(&dialog, wxID_ANY, "Connect...");
309	    connect->Bind(wxEVT_BUTTON, [&](wxCommandEvent&) {
310	        const auto index = std::size_t(clients->GetSelection());
311	        const auto& selected = entries[index];
312	        try {
313	            if (!std::filesystem::is_regular_file(bridge))
314	                throw std::runtime_error("The bundled MCP helper is missing. Reinstall or rebuild JusPrin.");
315	            if (!std::filesystem::is_regular_file(launcher))
316	                throw std::runtime_error("The AppImage launcher is missing. Reopen the installed AppImage.");
317	            if (selected.cli) {
318	                const auto cli = command_path(selected.id);
319	                if (cli.empty()) throw std::runtime_error("Client CLI was not found. Install it or use Copy in your terminal.");
320	                std::vector<std::string> arguments{cli};
321	                arguments.insert(arguments.end(), selected.arguments.begin(), selected.arguments.end());
322	                std::string command;
323	                for (const auto& argument : arguments) command += (command.empty() ? "" : " ") + Mcp::quote_argument(argument, windows);
324	                if (!confirm_setup(&dialog, "Run this command directly (no shell):\n\n" + command +
325	                    "\n\nThe client CLI manages its configuration. It may replace an existing JusPrin entry. Other servers are not removed.")) return;
326	                const auto result = run_mcp_setup_command(&dialog, arguments);
327	                status->SetLabel(wxString::FromUTF8((result.success ? "Configuration saved. Restart the client session to load JusPrin.\n" : "Setup failed.\n") + result.diagnostic));
328	            } else {
329	                const std::string root = selected.id == "code" ? "servers" : "mcpServers";
330	                const auto value = nlohmann::json::parse(selected.text);
331	                const auto edit = Mcp::prepare_json_connection(configs[index], root, value[root]["jusprin"]);
332	                if (!confirm_setup(&dialog, edit.preview)) return;
333	                const auto backup = Mcp::apply_config_edit(edit);
334	                status->SetLabel(wxString::FromUTF8("Configuration saved. Restart the client to load JusPrin." +
335	                    (backup.empty() ? "" : "\nBackup: " + backup.u8string())));
336	            }
337	        } catch (const std::exception& error) {
338	            // Client setup is an independent user operation. Show its failure;
339	            // keep the slicer usable and never report an unsuccessful write as connected.
340	            status->SetLabel(wxString::FromUTF8(std::string("Could not configure client: ") + error.what()));
341	        }
342	        status->Wrap(dialog.FromDIP(710));
343	        dialog.Layout();
344	    });
345	    buttons->Add(connect, 0, wxLEFT, gap);
346	    buttons->AddStretchSpacer();
347	    buttons->Add(new wxButton(&dialog, wxID_OK, "Close"));
348	    layout->Add(buttons, 0, wxEXPAND | wxALL, gap);
349	    dialog.SetSizer(layout);
350	    refresh();
351	    if (!std::filesystem::is_regular_file(bridge)) status->SetLabel("The bundled MCP helper is missing. Reinstall or rebuild JusPrin.");
352	    dialog.SetMinSize(dialog.FromDIP(wxSize(580, 440)));
353	    dialog.ShowModal();
354	}
