    29	void PrinterMenu::open(wxWindow* owner, const ShellTheme& theme, bool dark, Plater& plater, HeaderButton& anchor)
    30	{
    31	    auto self = std::make_shared<PrinterMenu>(owner, theme, dark, plater);
    32	    self->m_menu = new HeaderMenu(owner, theme, dark, {});
    33	    show_root(self);
    34	    self->m_menu->open(anchor);
    35	    // No dismiss listener: the row callbacks own the controller, so it lives
    36	    // until the last queued callback has run.
    37	}
    38	
    39	void PrinterMenu::show_root(const Ptr& self)
    40	{
    41	    auto* menu = self->m_menu.get();
    42	    if (menu == nullptr) return; // the popup went away; nothing to rebuild
    43	    const auto printer    = SetupCommands::current_printer();
    44	    const auto connection = SetupCommands::printer_connection();
    45	    const auto variants   = SetupCommands::nozzle_variants();
    46	    const auto plates     = SetupCommands::bed_types();
    47	
    48	    std::vector<HeaderMenuItem> rows;
    49	
    50	    // Row 1: the machine and what it is doing. A state JusPrin cannot observe
    51	    // reads as "Not connected" with a plain consequence, never as a guess and
    52	    // never in a warning colour -- the chip makes no claim about the machine.
    53	    HeaderMenuItem machine;
    54	    machine.label           = printer.nickname.empty() ? _L("No printer selected") : printer.nickname;
    55	    machine.decoration.bold = true;
    56	    machine.enabled         = connection.monitor_available;
    57	    switch (connection.state) {
    58	    case SetupCommands::ConnectionState::Idle:
    59	        machine.decoration.status      = StatusTone::Positive;
    60	        machine.decoration.status_word = _L("Idle");
    61	        machine.decoration.trailing    = HeaderIcon::Monitor;
    62	        break;
    63	    case SetupCommands::ConnectionState::Printing:
    64	        machine.decoration.status      = StatusTone::Busy;
    65	        machine.decoration.status_word = _L("Printing");
    66	        machine.decoration.trailing    = HeaderIcon::Monitor;
    67	        break;
    68	    case SetupCommands::ConnectionState::Offline:
    69	        machine.decoration.status      = StatusTone::Neutral;
    70	        machine.decoration.status_word = _L("Offline");
    71	        machine.decoration.trailing    = HeaderIcon::Monitor;
    72	        break;
    73	    case SetupCommands::ConnectionState::NotConnected:
    74	        machine.decoration.status      = StatusTone::Neutral;
    75	        machine.decoration.status_word = _L("Not connected");
    76	        // Connect… is deferred to a later slice, so the sub-line states the
    77	        // consequence rather than offering an action that would do nothing.
    78	        machine.decoration.sub_label = _L("Prints go to a card.");
    79	        break;
    80	    }
    81	    if (connection.monitor_available)
    82	        machine.invoke = [] { SetupCommands::open_monitor(); };
    83	    rows.push_back(std::move(machine));
    84	    rows.push_back(separator());
    85	
    86	    HeaderMenuItem nozzle;
    87	    nozzle.label                = _L("Nozzle");
    88	    nozzle.decoration.detail    = nozzle_text(printer.nozzle);
    89	    nozzle.decoration.technical = true;
    90	    nozzle.enabled              = !variants.empty();
    91	    if (nozzle.enabled) {
    92	        nozzle.decoration.trailing = HeaderIcon::Right;
    93	        nozzle.keeps_open          = true;
    94	        nozzle.invoke              = [self] { show_nozzles(self); };
    95	    }
    96	    rows.push_back(std::move(nozzle));
    97	
    98	    HeaderMenuItem plate;
    99	    plate.label = _L("Plate");
   100	    for (const auto& choice : plates)
   101	        if (choice.current) plate.decoration.detail = choice.label;
   102	    plate.enabled = !plates.empty();
   103	    if (plate.enabled) {
   104	        plate.decoration.trailing = HeaderIcon::Right;
   105	        plate.keeps_open          = true;
   106	        plate.invoke              = [self] { show_plates(self); };
   107	    }
   108	    rows.push_back(std::move(plate));
   109	    rows.push_back(separator());
   110	
   111	    HeaderMenuItem settings;
   112	    settings.label  = _L("Printer settings…");
   113	    settings.invoke = [] { SetupCommands::open_settings_tab(Preset::TYPE_PRINTER); };
   114	    rows.push_back(std::move(settings));
   115	
   116	    HeaderMenuItem add;
   117	    add.label = _L("Add a printer…");
   118	    // Deferred: this slice opens Orca's own wizard unchanged rather than the
   119	    // three-step sheet the design calls for.
   120	    add.invoke = [] { wxGetApp().run_wizard(ConfigWizard::RR_USER, ConfigWizard::SP_PRINTERS); };
   121	    rows.push_back(std::move(add));
   122	
   123	    menu->replace_items(std::move(rows));
   124	}
   125	
   126	void PrinterMenu::show_nozzles(const Ptr& self)
   127	{
   128	    std::vector<HeaderMenuItem> choices;
   129	    for (const auto& variant : SetupCommands::nozzle_variants()) {
   130	        HeaderMenuItem row;
   131	        row.label                = nozzle_text(variant.nozzle);
   132	        row.decoration.check     = variant.current;
   133	        row.invoke = [self, name = variant.preset_name] { SetupCommands::select_printer_preset(self->m_plater, name); };
   134	        choices.push_back(std::move(row));
   135	    }
   136	    show_sublist(self, _L("Nozzle"), std::move(choices));
   137	}
   138	
   139	void PrinterMenu::show_plates(const Ptr& self)
   140	{
   141	    std::vector<HeaderMenuItem> choices;
   142	    for (const auto& choice : SetupCommands::bed_types()) {
   143	        HeaderMenuItem row;
   144	        row.label            = choice.label;
   145	        row.decoration.check = choice.current;
   146	        row.invoke = [self, value = choice.value] { SetupCommands::select_bed_type(self->m_plater, value); };
   147	        choices.push_back(std::move(row));
   148	    }
   149	    show_sublist(self, _L("Plate"), std::move(choices));
   150	}
   151	
   152	void PrinterMenu::show_sublist(const Ptr& self, const wxString& title, std::vector<HeaderMenuItem> choices)
   153	{
   154	    auto* menu = self->m_menu.get();
   155	    if (menu == nullptr) return; // the popup went away; nothing to rebuild
   156	    std::vector<HeaderMenuItem> rows;
   157	    HeaderMenuItem back;
   158	    back.label      = title;
   159	    back.icon       = HeaderIcon::Back;
   160	    back.keeps_open = true;
   161	    back.invoke     = [self] { show_root(self); };
   162	    rows.push_back(std::move(back));
   163	    rows.push_back(separator());
   164	    for (auto& choice : choices) rows.push_back(std::move(choice));
   165	    menu->replace_items(std::move(rows));
   166	}
