    17	PrinterSpoolChip::PrinterSpoolChip(wxWindow* parent, const ShellTheme& theme)
    18	    : wxPanel(parent, wxID_ANY)
    19	{
    20	    SetName("Printer and spool");
    21	    // The halves paint edge to edge; the panel itself is never visible.
    22	    SetBackgroundStyle(wxBG_STYLE_PAINT);
    23	    Bind(wxEVT_PAINT, [](wxPaintEvent&) {});
    24	
    25	    m_printer = new HeaderButton(this, theme, HeaderStyle::ChipLeft, wxEmptyString, HeaderIcon::Printer);
    26	    m_printer->SetName("Printer");
    27	    m_printer->set_label_cap(kHalfLabelCapDip);
    28	    m_spool = new HeaderButton(this, theme, HeaderStyle::ChipRight, wxEmptyString, HeaderIcon::None);
    29	    m_spool->SetName("Spool");
    30	    m_spool->set_label_cap(kHalfLabelCapDip);
    31	
    32	    m_printer->Bind(wxEVT_BUTTON, [this](wxCommandEvent&) { if (m_printer_activated) m_printer_activated(); });
    33	    m_spool->Bind(wxEVT_BUTTON, [this](wxCommandEvent&) { if (m_spool_activated) m_spool_activated(); });
    34	
    35	    // Left and right move between the halves; the halves themselves keep
    36	    // Return and Space, which HeaderButton already handles.
    37	    auto arrows = [this](HeaderButton* self, HeaderButton* other) {
    38	        self->Bind(wxEVT_KEY_DOWN, [self, other](wxKeyEvent& event) {
    39	            const int key = event.GetKeyCode();
    40	            if (key == WXK_LEFT || key == WXK_RIGHT) {
    41	                if (self != other) other->SetFocus();
    42	                return;
    43	            }
    44	            event.Skip();
    45	        });
    46	    };
    47	    arrows(m_printer, m_spool);
    48	    arrows(m_spool, m_printer);
    49	
    50	    Bind(wxEVT_SIZE, [this](wxSizeEvent& event) { layout(); event.Skip(); });
    51	}
