    56	    m_printer->SetLabel(name);
    57	    HeaderRowDecoration decoration;
    58	    // "X1 Carbon · 0.4" reads as one line, with the nozzle in the teletype
    59	    // face the design system reserves for a measurement.
    60	    decoration.detail        = nozzle;
    61	    decoration.technical     = true;
    62	    decoration.detail_inline = true;
    63	    decoration.trailing  = HeaderIcon::Caret;
    64	    m_printer->set_decoration(std::move(decoration));
    65	    // The tooltip carries the full text the chip may have ellipsized. It says
    66	    // what is selected and nothing about whether it is loaded: the chip makes
    67	    // no claim about the physical machine.
    68	    m_printer->SetToolTip(nozzle.empty() ? name : name + wxString::FromUTF8(" \xC2\xB7 ") + nozzle + " mm");
    69	    InvalidateBestSize();
    70	    layout();
    71	}
