 57	{
 58	    SetName("Project header");
 59	    Workspace::SpoolStore::Config spool_config;
 60	    spool_config.file_path = (boost::filesystem::path(data_dir()) / "jusprin" / "spools.json").string();
 61	    m_spools = std::make_unique<Workspace::SpoolStore>(std::move(spool_config));
 62	    if (m_spools->corrupt()) {
 63	        // Visible, and the person's own file is preserved next to it. The chip
 64	        // still works: it reseeds from whatever the project has loaded.
 65	        BOOST_LOG_TRIVIAL(error) << "JusPrin: spools.json was damaged and has been moved aside: "
 66	                                 << m_spools->corrupt_reason();
 67	    }
 68	    SetBackgroundStyle(wxBG_STYLE_PAINT);
 69	    SetMinSize(wxSize(-1, FromDIP(56)));
 70	    m_home_button = new HeaderButton(this, theme, HeaderStyle::Quiet, _L("Home"), HeaderIcon::Back);
 71	    m_home_button->SetName("Home navigation");
 72	    m_chip = new PrinterSpoolChip(this, theme);
 73	    m_slice_button = new HeaderButton(this, theme, HeaderStyle::PrimaryLeft, _L("Slice"), HeaderIcon::Slice);
 74	    m_slice_button->SetName("Next print action");
 75	    m_menu_button = new HeaderButton(this, theme, HeaderStyle::PrimaryRight, wxEmptyString, HeaderIcon::Down);
 76	    m_menu_button->SetName(_L("Print actions"));
 77	    m_overflow_button = new HeaderButton(this, theme, HeaderStyle::Outline, wxEmptyString, HeaderIcon::More);
 78	    m_overflow_button->SetName("Project actions");
 79	    m_overflow_button->SetToolTip(_L("Project details and preferences"));
 80	    m_home_button->Bind(wxEVT_BUTTON, [this](wxCommandEvent&) { request_home(); });
 81	    m_chip->on_printer_activated([this] { open_printer_menu(); });
 82	    m_chip->on_spool_activated([this] { open_spool_menu(); });
 83	    m_overflow_button->Bind(wxEVT_BUTTON, [this](wxCommandEvent&) { show_overflow_menu(); });
 84	    Bind(wxEVT_SIZE, [this](wxSizeEvent& e) { layout_header(); e.Skip(); });
 85	    Bind(wxEVT_PAINT, [this](wxPaintEvent&) {
 86	        wxAutoBufferedPaintDC dc(this);
 87	        const auto& p = m_theme.palette(m_dark);
 88	        dc.SetBackground(wxBrush(p.surface_canvas)); dc.Clear();
 89	        dc.SetPen(wxPen(p.border_subtle));
 90	        dc.DrawLine(0, GetClientSize().y-1, GetClientSize().x, GetClientSize().y-1);
 91	    });
 92	
 93	    m_slice_button->Bind(wxEVT_BUTTON, [this](wxCommandEvent&) {
 94	        request_action(primary_print_action(action_state()).primary.action);
 95	    });
 96	    m_menu_button->Bind(wxEVT_BUTTON, [this](wxCommandEvent&) {
 97	        if (action_state().slicing) request_action(PrintAction::Cancel);
 98	        else show_action_menu();
 99	    });
100	
101	    Bind(wxEVT_SYS_COLOUR_CHANGED, [this](wxSysColourChangedEvent& event) {
102	        apply_appearance(GUI_App::dark_mode());
103	        event.Skip();
104	    });
105	
106	    m_project_state_subscription = m_plater.subscribe_project_state(
107	        [this](const ProjectStateChanged&) { refresh(); });
108	    // A recorded print and a replaced document both change the print count
109	    // without publishing a project-state change, so the ledger is observed
110	    // separately. Persistence outlives this row in both teardown orders, and
111	    // the destructor clears the slot.
112	    m_persistence.set_ledger_listener([this]() { refresh(); });
113	    m_reviews->set_listener([this]() { refresh(); });
114	    m_plater.Bind(EVT_SLICE_STATUS_CHANGED, &StatusRow::on_slice_status_changed, this);
115	    m_plater.Bind(EVT_SLICING_UPDATE, &StatusRow::on_slicing_progress, this);
116	    m_tabpanel.Bind(page_changed_event(), &StatusRow::on_tab_changed, this);
117	    // The tab panel and this row are siblings, so wx may destroy either one
118	    // first at shutdown; only unbind while the tab panel still exists.
119	    m_tabpanel.Bind(wxEVT_DESTROY, &StatusRow::on_tabpanel_destroyed, this);
120	}
