230	void StatusRow::refresh_workspace_status()
231	{
232	    if (!m_workspace_status || !m_tabpanel_alive) return;
233	    const auto& palette = m_theme.palette(m_dark);
234	    m_workspace_status->SetBackgroundColour(palette.surface_canvas);
235	    m_plate_label->SetForegroundColour(palette.text_secondary);
236	    m_return_button->set_dark(m_dark);
237	    m_review_panel->set_dark(m_dark);
238	    const auto state = action_state();
239	    const bool workspace = m_tabpanel.GetSelection() == MainFrame::tp3DEditor || m_tabpanel.GetSelection() == MainFrame::tpPreview;
240	    bool layout = m_workspace_status->Show(workspace);
241	    const bool preview = m_tabpanel.GetSelection() == MainFrame::tpPreview;
242	    const bool check = preview && state.preview && state.sliced && !state.slicing;
243	    layout = m_review_panel->Show(check) || layout;
244	    layout = m_return_button->Show(preview) || layout;
245	    if (check) m_review_panel->set_report(slice_identity(),m_reviews->findings(slice_identity()));
246	    auto* plate = m_plater.get_partplate_list().get_curr_plate();
247	    wxString label = wxString::Format(_L("Plate %d"),state.plate_number);
248	    if (plate && !plate->get_plate_name().empty()) label += " · " + wxString::FromUTF8(plate->get_plate_name());
249	    if (state.slicing) label += " · " + _L("Slicing…") + wxString::Format(" %.0f%%",plate ? std::clamp(double(plate->get_slicing_percent()),0.,100.) : 0.);
250	    else label += " · " + (state.sliced ? _L("sliced") : _L("not sliced"));
251	    m_plate_label->SetLabel(label);
252	    m_workspace_status->Layout();
253	    if (layout) m_workspace_status->GetParent()->Layout();
254	}
