263	
264	PrintActionState StatusRow::action_state() const
265	{
266	    PrintActionState state;
267	    auto& plates = m_plater.get_partplate_list();
268	    auto* plate = plates.get_curr_plate();
269	    state.slicing = m_plater.is_background_process_slicing();
270	    state.plate_number = plates.get_curr_plate_index() + 1;
271	    state.plate_count = plates.get_plate_count();
272	    state.preview = m_plater.is_preview_shown();
273	    const bool editable = !m_plater.only_gcode_mode() && !m_plater.using_exported_file();
274	    for (int i = 0; i < state.plate_count; ++i) {
275	        auto* item = plates.get_plate(i);
276	        if (item->is_slice_result_valid()) ++state.sliced_count;
277	        if (editable && item->can_slice() && !item->is_slice_result_valid()) state.can_slice_all = true;
278	    }
279	    if (plate) {
280	        state.sliced = plate->is_slice_result_valid();
281	        state.can_slice = editable && plate->can_slice();
282	        state.can_print = plate->is_slice_result_ready_for_print();
283	        state.can_export = plate->is_slice_result_ready_for_export();
284	    }
285	    auto* presets = wxGetApp().preset_bundle;
286	    // Match the native print-all backend support. Other legacy hosts accept
287	    // only one plate, even when several valid slices exist.
288	    bool supports_all = presets && presets->use_bbl_network();
289	    if (presets && !supports_all) {
290	        const auto& config = presets->printers.get_edited_preset().config;
291	        const auto* host = config.option<ConfigOptionEnum<PrintHostType>>("host_type");
292	        supports_all = host && host->value == htSimplyPrint;
293	    }
294	    state.can_print_all = supports_all && plates.is_all_slice_results_ready_for_print();
295	    state.needs_review = m_reviews->needs_review(slice_identity());
296	    return state;
297	}
