299	wxString StatusRow::action_label(PrintAction action, bool primary) const
300	{
301	    const auto state = action_state();
302	    switch (action) {
303	    case PrintAction::Slice: return _L("Slice");
304	    case PrintAction::SliceAll: return _L("Slice all plates");
305	    case PrintAction::Cancel: return primary ? _L("Slicing…") : _L("Cancel");
306	    case PrintAction::CheckPrint: return _L("Check print");
307	    case PrintAction::Print: return primary ? (state.plate_count > 1 ? wxString::Format(_L("Print plate %d"), state.plate_number) : _L("Print")) : _L("Print…");
308	    case PrintAction::PrintAll: return _L("Print all plates…");
309	    case PrintAction::Export: return _L("Export sliced file…");
310	    case PrintAction::Prepare: return _L("Back to Prepare");
311	    }
312	    throw std::logic_error("Unknown print action");
313	}
