315	void StatusRow::show_action_menu()
316	{
317	    const auto identity = slice_identity();
318	    const auto state = action_state();
319	    const auto actions = primary_print_action(state);
320	    std::vector<HeaderMenuItem> menu;
321	    for (const auto& item : actions.menu) {
322	        HeaderIcon icon = HeaderIcon::Slice;
323	        if (item.action == PrintAction::CheckPrint) icon = HeaderIcon::Eye;
324	        else if (item.action == PrintAction::Print) icon = HeaderIcon::Print;
325	        else if (item.action == PrintAction::PrintAll || item.action == PrintAction::SliceAll) icon = HeaderIcon::Plates;
326	        else if (item.action == PrintAction::Export) icon = HeaderIcon::Export;
327	        else if (item.action == PrintAction::Prepare) icon = HeaderIcon::Back;
328	        else if (item.action == PrintAction::Cancel) icon = HeaderIcon::Cancel;
329	        wxString detail;
330	        if (item.action == PrintAction::PrintAll)
331	            detail = wxString::Format(_L("%d sliced"), state.sliced_count);
332	        menu.push_back({action_label(item.action), icon, detail, item.enabled, item.action == PrintAction::Export || item.action == PrintAction::Prepare,
333	            [this,identity,action=item.action] {
334	                // The menu describes one plate/result. A later plate switch or
335	                // project replacement must not retarget that displayed command.
336	                if (slice_identity() == identity) request_action(action);
337	            }});
338	    }
339	    if (!menu.empty()) (new HeaderMenu(this,m_theme,m_dark,std::move(menu)))->open(*m_menu_button);
340	}
