342	void StatusRow::layout_header()
343	{
344	    const int margin = FromDIP(16), gap = FromDIP(8), height = GetClientSize().y;
345	    auto place = [height](HeaderButton* button, int x, int width = -1) {
346	        wxSize size = button->GetBestSize();
347	        if (width >= 0) size.x = width;
348	        button->SetSize(x,(height-size.y)/2,size.x,size.y);
349	    };
350	    int right = GetClientSize().x-margin-m_overflow_button->GetBestSize().x;
351	    place(m_overflow_button,right);
352	    right -= gap;
353	    if (m_menu_button->IsShown()) {
354	        right -= m_menu_button->GetBestSize().x;
355	        place(m_menu_button,right);
356	    }
357	    right -= m_slice_button->GetBestSize().x;
358	    place(m_slice_button,right);
359	    place(m_home_button,margin);
360	    const int left = margin+m_home_button->GetBestSize().x+gap;
361	    const int available = std::max(0,right-gap-left);
362	    const int width = std::min(m_chip->GetBestSize().x,available);
363	    const wxSize chip = m_chip->GetBestSize();
364	    m_chip->SetSize(left+(available-width)/2,(height-chip.y)/2,width,chip.y);
365	}
