381	std::optional<Workspace::Spool> StatusRow::current_spool()
382	{
383	    const auto printer  = SetupCommands::current_printer();
384	    const auto filament = SetupCommands::current_filament();
385	    if (!printer.valid || !filament.valid)
386	        return std::nullopt;
387	    const std::string colour = SetupCommands::current_colour().ToStdString();
388	
389	    if (auto matched = m_spools->current(printer.preset_name, filament.preset_name, colour))
390	        return matched;
391	    // A printer with no remembered spools gets its first one from whatever the
392	    // project already has loaded, so the chip's right half is never empty and
393	    // the person starts with a list of one rather than a list of none. A
394	    // printer that already has spools and is on some other preset simply has
395	    // no current spool; guessing a new one on every project would fill the
396	    // list with entries nobody chose.
397	    if (!m_spools->spools_for(printer.preset_name).empty())
398	        return std::nullopt;
399	
400	    Workspace::Spool seed;

